// Генератор финальной структуры EGE_CURRICULUM (Русский 100, Профиль 100, База 100, Физика 200)
const EGE_CURRICULUM = Object.entries(RAW_TOPICS_DATA).map(([subId, subData]) => {
  const count = subData.targetCount || 100;
  const topics = [];
  for (let i = 0; i < count; i++) {
    const src = subData.items[i % subData.items.length];
    const lap = Math.floor(i / subData.items.length);
    const suffix = lap > 0 ? ` · Практикум (вариант ${lap + 1})` : '';
    topics.push({
      id: `${subId}-${i + 1}`,
      block: src[0],
      title: `${i + 1}. ${src[1]}${suffix}`,
      note: src[2],
      question: src[3],
      answer: src[4],
      doneAt: null,
      stage: 0,
      solved: false
    });
  }
  return {
    id: subId,
    name: subData.name,
    icon: subData.icon,
    subtitle: subData.subtitle,
    minutes: 0,
    topics
  };
});